#include "modules/fem_mixed_api.h"
#include "runtime/thread_budget.hpp"
#include <algorithm>
#include <atomic>
#include <cmath>
#include <cstring>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
namespace {
unsigned checks=0,failures=0;void verify(bool value,const char* text){++checks;if(!value){++failures;std::cerr<<"FAIL "<<text<<'\n';}}
struct Model{bool nonlinear=false,flip=false;static int flux(void* raw,const double* state,uint32_t c,const double*,double* values,double* jac,char*,uint64_t){const auto& m=*static_cast<Model*>(raw);std::fill_n(values,3*c,0);if(jac)std::fill_n(jac,9*c*c,0);if(m.nonlinear){const auto u=state[0],dx=state[1],dy=state[2],d=1+u*u;values[0]=d*dx;values[1]=d*dy;if(jac){jac[0]=2*u*dx;jac[1]=d;jac[3]=2*u*dy;jac[5]=d;}}else{for(unsigned i=0;i<c;++i){values[i]=state[c+i];values[c+i]=state[2*c+i];values[2*c+i]=state[i]+(i==0?.1:.2)*state[1-i];if(jac){jac[i*3*c+c+i]=1;jac[(c+i)*3*c+2*c+i]=1;jac[(2*c+i)*3*c+i]=1;jac[(2*c+i)*3*c+1-i]=i==0?.1:.2;}}}return 0;}static int exact(void* raw,const double* p,uint32_t,double* values,uint64_t,char*,uint64_t){const auto& m=*static_cast<Model*>(raw);values[0]=p[0]+p[1];if(!m.nonlinear)values[1]=p[0]*p[0]*p[0]+p[1]*p[1]*p[1];return 0;}static int forcing(void* raw,const double* p,uint32_t,double* values,uint64_t,char*,uint64_t){const auto& m=*static_cast<Model*>(raw);const auto u=p[0]+p[1],v=p[0]*p[0]*p[0]+p[1]*p[1]*p[1];if(m.nonlinear)values[0]=-4*u;else{values[0]=u+.1*v;values[1]=-6*u+v+.2*u;}return 0;}};
struct Host{std::shared_ptr<std::atomic_bool> cancel=std::make_shared<std::atomic_bool>(false);penta::runtime::ParallelStatistics stats;std::size_t threads=4;static int cancelled(void* p){return static_cast<Host*>(p)->cancel->load();}static int parallel(void* p,uint64_t count,uint64_t cost,penta_numeric_range_task_v1 fn,void* raw,char* error,uint64_t cap){auto& self=*static_cast<Host*>(p);std::string failure;const auto status=penta::runtime::ThreadBudget::instance().run(count,cost,fn,raw,{self.threads,1},self.cancel,self.stats,failure);if(error&&cap){std::strncpy(error,failure.c_str(),cap-1);error[cap-1]=0;}return status;}};
struct Output{int status=0;penta_fem_mixed_result_v1 report{};std::vector<double> coordinates,values,visPoints,visValues;std::vector<uint64_t> offsets,faces;std::string error;};
Output run(Model& model,std::vector<uint32_t> orders,std::size_t threads=4,bool cancel=false){std::vector<double> points;std::vector<uint64_t> faces,boundaries;for(unsigned y=0;y<3;++y)for(unsigned x=0;x<3;++x)points.insert(points.end(),{x*.5,y*.5});for(uint64_t y=0;y<2;++y)for(uint64_t x=0;x<2;++x){const auto a=y*3+x+1,b=a+1,c=a+3,d=c+1;faces.insert(faces.end(),{a,b,d,a,d,c});}for(uint64_t j=0;j<2;++j){boundaries.insert(boundaries.end(),{j+1,j+2,1,3*(j+1),3*(j+2),2,9-j,8-j,3,7-3*j,4-3*j,4});}if(model.flip)for(std::size_t f=0;f<faces.size();f+=3)std::swap(faces[f],faces[f+1]);penta_fem_mixed_request_v1 q{};q.struct_size=sizeof(q);q.components=orders.size();q.visualization_refinement=4;q.vertices=9;q.triangles=8;q.boundaries=8;q.points=points.data();q.faces=faces.data();q.boundary_tags=boundaries.data();q.orders=orders.data();q.flux=Model::flux;q.flux_context=&model;q.forcing=Model::forcing;q.forcing_context=&model;q.dirichlet=q.exact=Model::exact;q.dirichlet_context=q.exact_context=&model;q.max_newton=30;q.max_linear=1000;q.gmres_restart=40;q.max_work=1000000000;q.max_bytes=256*1024*1024;q.max_seconds=60;q.rtol=1e-10;q.atol=1e-12;q.linear_tolerance=1e-11;uint64_t dofs=0;for(const auto p:orders)dofs+=9+24*(p-1)+(p>=3?4*(p-1)*(p-2):0);Output output;output.coordinates.resize(2*dofs);output.values.resize(dofs);output.visPoints.resize(240);output.visValues.resize(120*q.components);output.faces.resize(384);output.offsets.resize(q.components+1);auto& r=output.report;r.struct_size=sizeof(r);r.dof_capacity=dofs;r.vertex_capacity=120;r.triangle_capacity=128;r.coordinates=output.coordinates.data();r.values=output.values.data();r.component_offsets=output.offsets.data();r.visualization_coordinates=output.visPoints.data();r.visualization_values=output.visValues.data();r.visualization_faces=output.faces.data();Host context;context.threads=threads;context.cancel->store(cancel);penta_fem_parallel_host_v1 host{};host.base={sizeof(host),PENTA_FEM_ABI_V1,&context,Host::cancelled,nullptr};host.threads_requested=host.threads_granted=threads;host.parallel_for=Host::parallel;char error[1024]{};penta::runtime::ThreadBudget::instance().withReservation([&]{output.status=penta_fem_mixed_query_v1(PENTA_FEM_MIXED_ABI_V1)->solve(&host.base,&q,&r,error,sizeof(error));});output.error=error;if(output.status&&!cancel)std::cerr<<"Mixed FEM: "<<error<<'\n';return output;}
}
int main(){Model coupled;const auto mixed=run(coupled,{1,3});verify(!mixed.status&&mixed.report.converged,"Mixed P1/P3 coupled H1 weak system converges");verify(!mixed.status&&mixed.offsets[0]==1&&mixed.offsets[1]==10&&mixed.offsets[2]>mixed.offsets[1]+9,"Different state blocks retain distinct DOF counts and offsets");verify(!mixed.status&&mixed.report.l2_error<1e-8&&mixed.report.residual_norm<1e-8,"Independent linear/cubic manufactured exact solution");double error=0;if(!mixed.status)for(uint64_t at=0;at<mixed.report.dofs;++at){const auto x=mixed.coordinates[2*at],y=mixed.coordinates[2*at+1],expected=at<mixed.offsets[1]-1?x+y:x*x*x+y*y*y;error=std::max(error,std::abs(mixed.values[at]-expected));}verify(error<1e-8,"All ragged H1 coefficients reproduce their own polynomial space");Model nonlinear;nonlinear.nonlinear=true;const auto quasi=run(nonlinear,{2});verify(!quasi.status&&quasi.report.converged&&quasi.report.newton_iterations>1,"State-dependent diffusion uses nonlinear weak flux and analytic full chain Jacobian");verify(!quasi.status&&quasi.report.l2_error<1e-8&&quasi.report.jacobian_evaluations>0,"Independent -(div((1+u^2)grad(u))) manufactured solution");const auto serial=run(coupled,{1,3},1);bool same=!serial.status&&!mixed.status;for(uint64_t at=0;same&&at<mixed.report.dofs;++at)same=std::abs(serial.values[at]-mixed.values[at])<1e-12;verify(same,"Shared-budget parallel vector/Krylov path preserves serial numerical results");Model reversed;reversed.flip=true;const auto orientation=run(reversed,{1,3});verify(!orientation.status&&orientation.report.l2_error<1e-8,"Clockwise physical triangle orientation preserves mixed H1 bases and gradients");verify(run(nonlinear,{2},4,true).status==3,"Mixed H1 solve cancellation is cooperative");std::cout<<checks<<" mixed H1 FEM checks, "<<failures<<" failures\n";return failures?1:0;}
